    private final Logger log = LoggerFactory.getLogger(IBORController.class);

    @Value("${spring.datasource.new.username}")
    private String databaseUser;

    @Value("${spring.datasource.new.password}")
    private String databasePassword;

    @Value("${spring.datasource.new.url}")
    private String databaseUrl;

    @Value("${spring.datasource.prod.username}")
    private String databaseUserProd;

    @Value("${spring.datasource.prod.password}")
    private String databasePasswordProd;

    @Value("${spring.datasource.prod.url}")
    private String databaseUrlProd;

    public static boolean isNullOrEmpty(final Object obj) {
        if (obj == null) {
            return true;
        }
        if (obj.getClass().equals(Collection.class)) {
            return ((Collection) obj).size() == 0;
        } else {
            if (obj.toString().trim().length() == 0) {
                return true;
            }
        }

        return false;
    }


    /*
   Metoda prihvata kao ulazne parametare:
   -Language
   -ProductType
   -InterestID
   Cita podatke iz tabela sa core-a: beday03a.SDFVVP, bbeday03a.eday03aCFLEP, begpl.iboriratp filtrira  i izlaze JSON.
    */
    @RequestMapping(value = "/ibor/GetInterestRate", method = RequestMethod.POST)
    public IBOR_INTEREST_RATES_RESPONSE_RC GetInterestRate (@RequestBody IBOR_INTEREST_RATES_REQUEST REQ) throws Exception  {


        IBOR_INTEREST_RATES_RESPONSE_RC res = new IBOR_INTEREST_RATES_RESPONSE_RC();
        res.setResponseCode("N");
        res.setMessageText("");

        List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate = new ArrayList<>();

        System.out.println(" iz requesta Language:  " + REQ.getLanguage());
        String languagereq = REQ.getLanguage();

        String productType_req = REQ.getProductType();
        if (productType_req != null) {
            productType_req = productType_req.toUpperCase().trim();
        }
        System.out.println(" iz requesta ProductType_req:  " + productType_req);
        if (languagereq.equalsIgnoreCase("EN")) languagereq="ENG";

        if ((languagereq.equalsIgnoreCase("RS") && productType_req!=null && productType_req.equalsIgnoreCase("CREDIT")))
            productType_req = "KREDIT";

        if ((languagereq.equalsIgnoreCase("RS") && productType_req!=null && productType_req.equalsIgnoreCase("SAVING ACCOUNT")))
            productType_req = "Å TEDNI RAÄŒUN";

        System.out.println(" productType_req:  " + productType_req);

        System.out.println(" iz requesta InterestID:  " + REQ.getInterestID());
        String InterestID_req = REQ.getInterestID();
        if (InterestID_req != null) {
            InterestID_req = InterestID_req.toUpperCase().trim();
        }
        //  Konekcija na AS400
        DriverManager.registerDriver(new com.ibm.as400.access.AS400JDBCDriver());
        Connection con = DriverManager.getConnection
                (databaseUrl, databaseUser, databasePassword);
        String query;

        if (languagereq!=null && languagereq.equalsIgnoreCase("RS")){
            System.out.println("Srpski  svi tipovi ProductType ");
            query = "select  lpad(BRC,5,'0')||lpad(Currency_Code,3,'0') InterestID,\n" +
                    "                           (case when upper(Product_Type)='CREDIT' then 'KREDIT'\n" +
                    "                            when upper(Product_Type)='SAVING ACCOUNT' then 'Å TEDNI RAÄŒUN' else Product_Type END) Product_Type, \n" +
                    "                            Interest_Rate_Name,\n" +
                    "                            (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'dd.mm.yyyy') else Update_Frequency_RS end) Update_Frequency_RS,\n" +
                    "                            '' Update_Frequency_ENG,\n" +
                    "                            (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'YYYYMMDD') else Rate_Effective_DATE_NEW end) Last_Update,\n" +
                    "                            Interest_Rate_Value\n" +
                    "                    from            \n" +
                    "                        (SELECT  T3.Product_Type,\n" +
                    "                                T3.Interest_Rate_Name,\n" +
                    "                                T3.Update_Frequency Update_Frequency_Rs,\n" +
                    "                                T3.Update_Frequency_Eng,\n" +
                    "                                T3.SORT,\n" +
                    "                                concat(VARCHAR_FORMAT(t1.svvcrt,'0.000' ),'%') Interest_Rate_Value,\n" +
                    "                                    t1.svvbrt BRC,\n" +
                    "                                    t1.svvccy Currency_Code, \n" +
                    "                                    cfshna Currency_Name,\n" +
                    "                                    t1.svvrcd Rate_Change_Date,\n" +
                    "                                    t1.SVVRED  Rate_Effective_DATE,\n" +
                    "                                    t1.svvbrd Base_Rate_Desc,\n" +
                    "                                    t1.svvacd Description2,\n" +
                    "                                    t1.SVVPRI Previous_Rate,\n" +
                    "                                    nvl(T5.FVQROD,0) RateOffset,\n" +
                    "                                    VARCHAR_FORMAT(DATE(TIMESTAMP_FORMAT(CHAR(t1.SVVRED), 'YYYYMMDD') - nvl(T5.FVQROD,0) days), 'YYYYMMDD') Rate_Effective_DATE_NEW\n" +
                    "                            FROM begpl.iboriratp T3                                                            \n" +
                    "                                        INNER JOIN BEEOD03A.SDFVVP t1  ON T3.BRC=T1.SVVBRT AND T3.CCY= T1.SVVCCY      \n" +
                    "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM BEDAY03A.SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
                    "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
                    "                                    INNER JOIN beday03A.CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
                    "                                    LEFT JOIN BEEOD03A.CAFVQP T5 ON T5.FVQBRC=T1.SVVBRT AND T5.FVQCCY=T1.SVVCCY \n" +
                    "                        ) tab          \n" +
                    "                    order by Product_Type,SORT";
        }
        else if (languagereq!=null && languagereq.equalsIgnoreCase("ENG")){
            System.out.println("Engleski  " );
            query = "select  lpad(BRC,5,'0')||lpad(Currency_Code,3,'0') InterestID,\n" +
                    "                           Product_Type, \n" +
                    "                            Interest_Rate_Name,\n" +
                    "                            '' Update_Frequency_RS,\n" +
                    "                    (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'dd.mm.yyyy') else nvl(Update_Frequency_Eng,Update_Frequency_RS) end) Update_Frequency_ENG,\n" +
                    "                    (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'YYYYMMDD') else Rate_Effective_DATE_NEW end) Last_Update,\n" +
                    "                    Interest_Rate_Value\n" +
                    "                    from            \n" +
                    "                        (SELECT  T3.Product_Type,\n" +
                    "                                T3.Interest_Rate_Name,\n" +
                    "                                T3.Update_Frequency Update_Frequency_Rs,\n" +
                    "                                T3.Update_Frequency_Eng,\n" +
                    "                                T3.SORT,\n" +
                    "                                concat(VARCHAR_FORMAT(t1.svvcrt,'0.000' ),'%') Interest_Rate_Value,\n" +
                    "                                    t1.svvbrt BRC,\n" +
                    "                                    t1.svvccy Currency_Code, \n" +
                    "                                    cfshna Currency_Name,\n" +
                    "                                    t1.svvrcd Rate_Change_Date,\n" +
                    "                                    t1.SVVRED  Rate_Effective_DATE,\n" +
                    "                                    t1.svvbrd Base_Rate_Desc,\n" +
                    "                                    t1.svvacd Description2,\n" +
                    "                                    t1.SVVPRI Previous_Rate,\n" +
                    "                                    nvl(T5.FVQROD,0) RateOffset,\n" +
                    "                                    VARCHAR_FORMAT(DATE(TIMESTAMP_FORMAT(CHAR(t1.SVVRED), 'YYYYMMDD') - nvl(T5.FVQROD,0) days), 'YYYYMMDD') Rate_Effective_DATE_NEW\n" +
                    "                            FROM begpl.iboriratp T3                                                            \n" +
                    "                                        INNER JOIN BEEOD03A.SDFVVP t1  ON T3.BRC=T1.SVVBRT AND T3.CCY= T1.SVVCCY      \n" +
                    "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM BEDAY03A.SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
                    "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
                    "                                    INNER JOIN beday03A.CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
                    "                                    LEFT JOIN BEEOD03A.CAFVQP T5 ON T5.FVQBRC=T1.SVVBRT AND T5.FVQCCY=T1.SVVCCY \n" +
                    "                        ) tab          \n" +
                    "                    order by Product_Type,SORT";
        }
        else {
            res.setResponseCode("N");
            res.setMessageText("No data found");
            return res;
        }

        System.out.println("query:  " + query);
        try (PreparedStatement preparedStatement = con.prepareStatement(query)) {
            ResultSet rs = preparedStatement.executeQuery();
            while (rs.next()) {
                String update_Frequency_response =
                        isNullOrEmpty(rs.getString("Update_Frequency_RS")) ? rs.getString("Update_Frequency_ENG") :
                                rs.getString("Update_Frequency_RS");
                String InterestID = rs.getString("InterestID").trim();
                String Product_Type = rs.getString("Product_Type").trim();
                String Interest_Rate_Name = rs.getString("Interest_Rate_Name").trim();
                update_Frequency_response = update_Frequency_response.trim();
                String Last_Update = rs.getString("Last_Update").trim();
                String Interest_Rate_Value = rs.getString("Interest_Rate_Value").trim();

                IBOR_INTEREST_RATES_RESPONSE pojedinacni = new IBOR_INTEREST_RATES_RESPONSE();
                pojedinacni.setInterestID(InterestID);
                pojedinacni.setProduct_Type(Product_Type);
                pojedinacni.setInterest_Rate_Name(Interest_Rate_Name);
                pojedinacni.setUpdate_Frequency(update_Frequency_response);
                pojedinacni.setLast_Update(Last_Update);
                pojedinacni.setInterest_Rate_Value(Interest_Rate_Value);

                listaInterestRate.add(pojedinacni);

                if (!isNullOrEmpty(productType_req)) {
                    switch (productType_req) {
                        case "CREDIT":
                            List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate_credit = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProduct_Type().equalsIgnoreCase("CREDIT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_credit;
                            break;
                        case "KREDIT":
                            List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate_kredit = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProduct_Type().equalsIgnoreCase("KREDIT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_kredit;
                            break;
                        case "SAVING ACCOUNT":
                            List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate_sa = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProduct_Type().equalsIgnoreCase("SAVING ACCOUNT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_sa;
                            break;
                        case "Å TEDNI RAÄŒUN":
                            List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate_stedni = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProduct_Type().equalsIgnoreCase("Å TEDNI RAÄŒUN"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_stedni;
                            break;
                    }
                }
                if (!isNullOrEmpty(InterestID_req)) {
                    //   System.out.println(" Filtriraj za InterestID :  " + InterestID_req);
                    String InterestID_req_temp = InterestID_req;
                    List<IBOR_INTEREST_RATES_RESPONSE> listaInterestRate_ID = listaInterestRate
                            .stream()
                            .filter(c -> c.getInterestID().equalsIgnoreCase(InterestID_req_temp))
                            .collect(Collectors.toList());
                    listaInterestRate = listaInterestRate_ID;
                }
                res.setResponseCode("Y");
                res.setIBOR(listaInterestRate);
                res.setMessageText("");

                if (listaInterestRate.size() == 0) {
                    res.setResponseCode("N");
                    res.setMessageText("No data found");
                }

            }
        } catch (Exception e) {
            res.setResponseCode("N");
            res.setMessageText("Internal error");
        }
        return res;
    }
