                    "                                    VARCHAR_FORMAT(DATE(TIMESTAMP_FORMAT(CHAR(t1.SVVRED), 'YYYYMMDD') - nvl(T5.FVQROD,0) days), 'YYYYMMDD') Rate_Effective_DATE_NEW\n" +
                    "                            FROM begpl.iboriratp T3                                                            \n" +
                    "                                        INNER JOIN BEEOD03A.SDFVVP t1  ON T3.BRC=T1.SVVBRT AND T3.CCY= T1.SVVCCY      \n" +
                    "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM BEDAY03A.SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
                    "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
                    "                                    INNER JOIN beday03A.CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
