                (databaseUrl, databaseUser, databasePassword);
        String query;

        if (languagereq!=null && languagereq.equalsIgnoreCase("RS")){
            System.out.println("Srpski  svi tipovi ProductType ");
            query = "select  lpad(BRC,5,'0')||lpad(Currency_Code,3,'0') InterestID,\n" +
                    "                           (case when upper(Product_Type)='CREDIT' then 'KREDIT'\n" +
                    "                            when upper(Product_Type)='SAVING ACCOUNT' then 'Å TEDNI RAÄŒUN' else Product_Type END) Product_Type, \n" +
                    "                            Interest_Rate_Name,\n" +
