                    "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM BEDAY03A.SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
                    "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
                    "                                    INNER JOIN beday03A.CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
                    "                                    LEFT JOIN BEEOD03A.CAFVQP T5 ON T5.FVQBRC=T1.SVVBRT AND T5.FVQCCY=T1.SVVCCY \n" +
                    "                        ) tab          \n" +
                    "                    order by Product_Type,SORT";
        }
        else if (languagereq!=null && languagereq.equalsIgnoreCase("ENG")){
            System.out.println("Engleski  " );
            query = "select  lpad(BRC,5,'0')||lpad(Currency_Code,3,'0') InterestID,\n" +
                    "                           Product_Type, \n" +
                    "                            Interest_Rate_Name,\n" +
                    "                            '' Update_Frequency_RS,\n" +
                    "                    (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'dd.mm.yyyy') else nvl(Update_Frequency_Eng,Update_Frequency_RS) end) Update_Frequency_ENG,\n" +
                    "                    (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'YYYYMMDD') else Rate_Effective_DATE_NEW end) Last_Update,\n" +
