                res.setMessageText("");

                if (listaInterestRate.size() == 0) {
                    res.setResponseCode("N");
                    res.setMessageText("No data found");
                }

            }
        } catch (Exception e) {
            res.setResponseCode("N");
            res.setMessageText("Internal error");
        }
        return res;
