+    private String buildInterestRateQuery(String language) {
+        if (language == null) {
+            return null;
+        }
+
+        String schema = daySchema;
+        String productTypeExpression;
+        String updateFrequencyRsExpression;
+        String updateFrequencyEngExpression;
+
+        if (language.equalsIgnoreCase("RS")) {
+            productTypeExpression = "(case when upper(Product_Type)='CREDIT' then 'KREDIT' " +
+                    "when upper(Product_Type)='SAVING ACCOUNT' then 'ŠTEDNI RAČUN' else Product_Type END)";
+            updateFrequencyRsExpression = "(case when upper(Product_Type)='SAVING ACCOUNT' " +
+                    "then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'dd.mm.yyyy') else Update_Frequency_RS end)";
+            updateFrequencyEngExpression = "''";
+        } else if (language.equalsIgnoreCase("ENG")) {
+            productTypeExpression = "Product_Type";
+            updateFrequencyRsExpression = "''";
+            updateFrequencyEngExpression = "(case when upper(Product_Type)='SAVING ACCOUNT' " +
+                    "then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'dd.mm.yyyy') else nvl(Update_Frequency_Eng,Update_Frequency_RS) end)";
+        } else {
+            return null;
+        }
+
+        return "select  lpad(BRC,5,'0')||lpad(Currency_Code,3,'0') InterestID,\n" +
+                "                           " + productTypeExpression + " Product_Type,\n" +
+                "                            Interest_Rate_Name,\n" +
+                "                            " + updateFrequencyRsExpression + " Update_Frequency_RS,\n" +
+                "                            " + updateFrequencyEngExpression + " Update_Frequency_ENG,\n" +
+                "                            (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'YYYYMMDD') else Rate_Effective_DATE_NEW end) Last_Update,\n" +
+                "                            Interest_Rate_Value\n" +
+                "                    from            \n" +
+                "                        (SELECT  T3.Product_Type,\n" +
+                "                                T3.Interest_Rate_Name,\n" +
+                "                                T3.Update_Frequency Update_Frequency_Rs,\n" +
+                "                                T3.Update_Frequency_Eng,\n" +
+                "                                T3.SORT,\n" +
+                "                                concat(VARCHAR_FORMAT(t1.svvcrt,'0.000' ),'%') Interest_Rate_Value,\n" +
+                "                                    t1.svvbrt BRC,\n" +
+                "                                    t1.svvccy Currency_Code, \n" +
+                "                                    cfshna Currency_Name,\n" +
+                "                                    t1.svvrcd Rate_Change_Date,\n" +
+                "                                    t1.SVVRED  Rate_Effective_DATE,\n" +
+                "                                    t1.svvbrd Base_Rate_Desc,\n" +
+                "                                    t1.svvacd Description2,\n" +
+                "                                    t1.SVVPRI Previous_Rate,\n" +
+                "                                    nvl(T5.FVQROD,0) RateOffset,\n" +
+                "                                    VARCHAR_FORMAT(DATE(TIMESTAMP_FORMAT(CHAR(t1.SVVRED), 'YYYYMMDD') - nvl(T5.FVQROD,0) days), 'YYYYMMDD') Rate_Effective_DATE_NEW\n" +
+                "                            FROM begpl.iboriratp T3                                                            \n" +
+                "                                        INNER JOIN " + schema + ".SDFVVP t1  ON T3.BRC=T1.SVVBRT AND T3.CCY= T1.SVVCCY      \n" +
+                "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM " + schema + ".SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
+                "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
+                "                                    INNER JOIN " + schema + ".CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
+                "                                    LEFT JOIN " + schema + ".CAFVQP T5 ON T5.FVQBRC=T1.SVVBRT AND T5.FVQCCY=T1.SVVCCY \n" +
+                "                        ) tab          \n" +
+                "                    order by Product_Type,SORT";
+    }
