package rs.unicreditbank.ucbservices.Controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RestController;
import rs.unicreditbank.ucbservices.dto.ibor.IborInterestRateResponse;
import rs.unicreditbank.ucbservices.dto.ibor.IborInterestRatesRequest;
import rs.unicreditbank.ucbservices.dto.ibor.IborInterestRatesResponse;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

@RestController
public class IBORController {

    @Value("${spring.datasource.username}")
    private String databaseUser;

    @Value("${spring.datasource.password}")
    private String databasePassword;

    @Value("${spring.datasource.url}")
    private String databaseUrl;

    @Value("${app.db2.day-schema:beday03A}")
    private String daySchema;

    public static boolean isNullOrEmpty(final Object obj) {
        if (obj == null) {
            return true;
        }
        if (obj.getClass().equals(Collection.class)) {
            return ((Collection) obj).size() == 0;
        } else {
            if (obj.toString().trim().length() == 0) {
                return true;
            }
        }

        return false;
    }


    /*
   Metoda prihvata kao ulazne parametare:
   -Language
   -ProductType
   -InterestID
   Cita podatke iz tabela sa core-a: beday03a.SDFVVP, bbeday03a.eday03aCFLEP, begpl.iboriratp filtrira  i izlaze JSON.
    */
    @RequestMapping(value = "/ibor/GetInterestRate", method = RequestMethod.POST)
    public IborInterestRatesResponse GetInterestRate (@RequestBody IborInterestRatesRequest REQ) throws Exception  {


        IborInterestRatesResponse res = new IborInterestRatesResponse();
        res.setResponseCode("N");
        res.setMessageText("");

        List<IborInterestRateResponse> listaInterestRate = new ArrayList<>();

        System.out.println(" iz requesta Language:  " + REQ.getLanguage());
        String languagereq = REQ.getLanguage();

        String productType_req = REQ.getProductType();
        if (productType_req != null) {
            productType_req = productType_req.toUpperCase().trim();
        }
        System.out.println(" iz requesta ProductType_req:  " + productType_req);
        if ("EN".equalsIgnoreCase(languagereq)) languagereq="ENG";

        if (("RS".equalsIgnoreCase(languagereq) && productType_req!=null && productType_req.equalsIgnoreCase("CREDIT")))
            productType_req = "KREDIT";

        if (("RS".equalsIgnoreCase(languagereq) && productType_req!=null && productType_req.equalsIgnoreCase("SAVING ACCOUNT")))
            productType_req = "Å TEDNI RAÄŒUN";

        System.out.println(" productType_req:  " + productType_req);

        System.out.println(" iz requesta InterestID:  " + REQ.getInterestId());
        String InterestID_req = REQ.getInterestId();
        if (InterestID_req != null) {
            InterestID_req = InterestID_req.toUpperCase().trim();
        }
        if ("RS".equalsIgnoreCase(languagereq)){
            System.out.println("Srpski  svi tipovi ProductType ");
        } else if ("ENG".equalsIgnoreCase(languagereq)){
            System.out.println("Engleski  " );
        }

        String query = buildInterestRateQuery(languagereq);
        if (query == null) {
            res.setResponseCode("N");
            res.setMessageText("No data found");
            return res;
        }

        //  Konekcija na AS400
        DriverManager.registerDriver(new com.ibm.as400.access.AS400JDBCDriver());
        Connection con = DriverManager.getConnection
                (databaseUrl, databaseUser, databasePassword);

        System.out.println("query:  " + query);
        try (PreparedStatement preparedStatement = con.prepareStatement(query)) {
            ResultSet rs = preparedStatement.executeQuery();
            while (rs.next()) {
                String update_Frequency_response =
                        isNullOrEmpty(rs.getString("Update_Frequency_RS")) ? rs.getString("Update_Frequency_ENG") :
                                rs.getString("Update_Frequency_RS");
                String InterestID = rs.getString("InterestID").trim();
                String Product_Type = rs.getString("Product_Type").trim();
                String Interest_Rate_Name = rs.getString("Interest_Rate_Name").trim();
                update_Frequency_response = update_Frequency_response.trim();
                String Last_Update = rs.getString("Last_Update").trim();
                String Interest_Rate_Value = rs.getString("Interest_Rate_Value").trim();

                IborInterestRateResponse pojedinacni = new IborInterestRateResponse();
                pojedinacni.setInterestId(InterestID);
                pojedinacni.setProductType(Product_Type);
                pojedinacni.setInterestRateName(Interest_Rate_Name);
                pojedinacni.setUpdateFrequency(update_Frequency_response);
                pojedinacni.setLastUpdate(Last_Update);
                pojedinacni.setInterestRateValue(Interest_Rate_Value);

                listaInterestRate.add(pojedinacni);

                if (!isNullOrEmpty(productType_req)) {
                    switch (productType_req) {
                        case "CREDIT":
                            List<IborInterestRateResponse> listaInterestRate_credit = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProductType().equalsIgnoreCase("CREDIT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_credit;
                            break;
                        case "KREDIT":
                            List<IborInterestRateResponse> listaInterestRate_kredit = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProductType().equalsIgnoreCase("KREDIT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_kredit;
                            break;
                        case "SAVING ACCOUNT":
                            List<IborInterestRateResponse> listaInterestRate_sa = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProductType().equalsIgnoreCase("SAVING ACCOUNT"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_sa;
                            break;
                        case "Å TEDNI RAÄŒUN":
                            List<IborInterestRateResponse> listaInterestRate_stedni = listaInterestRate
                                    .stream()
                                    .filter(c -> c.getProductType().equalsIgnoreCase("Å TEDNI RAÄŒUN"))
                                    .collect(Collectors.toList());
                            listaInterestRate = listaInterestRate_stedni;
                            break;
                    }
                }
                if (!isNullOrEmpty(InterestID_req)) {
                    //   System.out.println(" Filtriraj za InterestID :  " + InterestID_req);
                    String InterestID_req_temp = InterestID_req;
                    List<IborInterestRateResponse> listaInterestRate_ID = listaInterestRate
                            .stream()
                            .filter(c -> c.getInterestId().equalsIgnoreCase(InterestID_req_temp))
                            .collect(Collectors.toList());
                    listaInterestRate = listaInterestRate_ID;
                }
                res.setResponseCode("Y");
                res.setReferenceRateInfo(listaInterestRate);
                res.setMessageText("");

                if (listaInterestRate.size() == 0) {
                    res.setResponseCode("N");
                    res.setMessageText("No data found");
                }

            }
        } catch (Exception e) {
            res.setResponseCode("N");
            res.setMessageText("Internal error");
        }
        return res;
    }

    private String buildInterestRateQuery(String language) {
        if (language == null) {
            return null;
        }

        String schema = daySchema;
        String productTypeExpression;
        String updateFrequencyRsExpression;
        String updateFrequencyEngExpression;

        if (language.equalsIgnoreCase("RS")) {
            productTypeExpression = "(case when upper(Product_Type)='CREDIT' then 'KREDIT' " +
