                "                            " + updateFrequencyRsExpression + " Update_Frequency_RS,\n" +
                "                            " + updateFrequencyEngExpression + " Update_Frequency_ENG,\n" +
                "                            (case when upper(Product_Type)='SAVING ACCOUNT' then VARCHAR_FORMAT(CURRENT TIMESTAMP, 'YYYYMMDD') else Rate_Effective_DATE_NEW end) Last_Update,\n" +
                "                            Interest_Rate_Value\n" +
                "                    from            \n" +
