                "                                T3.Update_Frequency Update_Frequency_Rs,\n" +
                "                                T3.Update_Frequency_Eng,\n" +
                "                                T3.SORT,\n" +
                "                                concat(VARCHAR_FORMAT(t1.svvcrt,'0.000' ),'%') Interest_Rate_Value,\n" +
                "                                    t1.svvbrt BRC,\n" +
                "                                    t1.svvccy Currency_Code, \n" +
                "                                    cfshna Currency_Name,\n" +
                "                                    t1.svvrcd Rate_Change_Date,\n" +
                "                                    t1.SVVRED  Rate_Effective_DATE,\n" +
                "                                    t1.svvbrd Base_Rate_Desc,\n" +
                "                                    t1.svvacd Description2,\n" +
                "                                    t1.SVVPRI Previous_Rate,\n" +
                "                                    nvl(T5.FVQROD,0) RateOffset,\n" +
                "                                    VARCHAR_FORMAT(DATE(TIMESTAMP_FORMAT(CHAR(t1.SVVRED), 'YYYYMMDD') - nvl(T5.FVQROD,0) days), 'YYYYMMDD') Rate_Effective_DATE_NEW\n" +
                "                            FROM begpl.iboriratp T3                                                            \n" +
                "                                        INNER JOIN " + schema + ".SDFVVP t1  ON T3.BRC=T1.SVVBRT AND T3.CCY= T1.SVVCCY      \n" +
                "                                               INNER JOIN (SELECT SVVCCY,SVVBRT,max(SVVRED) SVVRED, max(SVVRCD) SVVRCD FROM " + schema + ".SDFVVP GROUP BY  SVVCCY,SVVBRT ) t4 \n" +
                "                                                                   ON t1.SVVCCY=t4.SVVCCY AND t1.SVVBRT=t4.SVVBRT AND t1.SVVRED=t4.SVVRED AND t1.SVVRCD=t4.SVVRCD\n" +
                "                                    INNER JOIN " + schema + ".CFLEP T2 ON T2.CFCCD=T1.SVVCCY    \n" +
                "                                    LEFT JOIN " + schema + ".CAFVQP T5 ON T5.FVQBRC=T1.SVVBRT AND T5.FVQCCY=T1.SVVCCY \n" +
                "                        ) tab          \n" +
                "                    order by Product_Type,SORT";
    }
}

